function T({registerIndicator:g,sourceValues:k,nulls:w}){g({id:"oa-trendflex",name:" Ehlers Trendflex Indicator (TRENDFLEX)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1,tooltip:"Lookback period for trend measurement."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"trendflex",type:"line",title:"TRENDFLEX",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(o,p){const t=Math.max(1,Math.floor(Number(p.period)||20)),i=k(o,p.source??"close"),h=t*.5,s=Math.exp(-1.414*Math.PI/h),m=2*s*Math.cos(1.414*Math.PI/h),y=-(s*s),E=1-m-y,l=new Array(o.length);for(let e=0;e<o.length;e++)l[e]=Number.isFinite(i[e])?i[e]:0;let a=0,b=0;const x=new Array(t).fill(0);let n=0,u=0,f=0,r=0;const M=new Array(o.length).fill(NaN);for(let e=0;e<o.length;e++){const P=e>0?l[e-1]:0,c=e<2?l[e]:E*(l[e]+P)*.5+m*a+y*b;b=a,a=c;const N=Math.min(f,t),d=N>0?(N*c-u)/t:0;u-=x[n],u+=c,x[n]=c,n=(n+1)%t,f<t&&(f+=1),r=.04*d*d+.96*r;const F=r>0?d/Math.sqrt(r):0;Number.isFinite(i[e])&&Number.isFinite(F)&&(M[e]=F)}return{trendflex:w(M)}}})}export{T as default};
